108	            return null;
109	        }
110	        int sum = 0;
111	        boolean dbl = true;
112	        for (int i = customerCode.length() - 1; i >= 0; i--) {
113	            char c = customerCode.charAt(i);
114	            if (c < '0' || c > '9') {
115	                continue;
116	            }
117	            int d = c - '0';
118	            if (dbl) {
119	                d *= 2;
120	                if (d > 9) {
121	                    d -= 9;
122	                }
123	            }
124	            sum += d;
125	            dbl = !dbl;
126	        }
127	        return (10 - (sum % 10)) % 10;
