96	    default boolean bulkSignupWarning(Owner owner) {
97	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
98	    }
99	
100	    /**
101	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
102	     * in {@code customerCode}, derived at read time. Returns {@code null} when no customer code has
103	     * been assigned.
104	     */
105	    default Integer checkDigit(Owner owner) {
106	        String customerCode = owner.getCustomerCode();
107	        if (customerCode == null) {
108	            return null;
109	        }
110	        int sum = 0;
111	        boolean dbl = true;
112	        for (int i = customerCode.length() - 1; i >= 0; i--) {
113	            char c = customerCode.charAt(i);
114	            if (c < '0' || c > '9') {
115	                continue;
116	            }
117	            int d = c - '0';
118	            if (dbl) {
119	                d *= 2;
120	                if (d > 9) {
121	                    d -= 9;
122	                }
123	            }
124	            sum += d;
125	            dbl = !dbl;
126	        }
127	        return (10 - (sum % 10)) % 10;
128	    }
129	
130	    /**
131	     * Derives the owner's membership points: starts at 0, adds 2 when an email is present, adds 1
132	     * when the owner had no namesakes at creation ({@code namesakeCount == 0}), adds 2 when the
133	     * owner belongs to a household of 3 or more members ({@code householdSize >= 3}, counted at
134	     * creation by {@code AssignHouseholdSize}), and adds 3 when the owner's tenure (days since
135	     * {@code registrationDate}) exceeds 365.
136	     */
137	    default int membershipPoints(Owner owner) {
138	        int points = 0;
139	        if (hasEmail(owner)) {
140	            points += 2;
141	        }
142	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
143	            points += 1;
144	        }
145	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
146	            points += 2;
147	        }
148	        if (tenureDays(owner) > 365) {
149	            points += 3;
150	        }
151	        return points;
152	    }
153	
154	    /**
155	     * Maps the owner's {@link #membershipPoints(Owner) membership points} to a numeric level:
156	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
157	     */
158	    default int membershipLevel(Owner owner) {
159	        int points = membershipPoints(owner);
160	        if (points <= 1) {
161	            return 1;
162	        }
163	        if (points <= 3) {
164	            return 2;
165	        }
166	        if (points <= 5) {
167	            return 3;
168	        }
169	        return 4;
170	    }
171	
172	    /**
173	     * The owner's tenure in whole days: the number of days from its {@code registrationDate} to
174	     * today. Returns 0 when no registration date is stored (or it lies in the future), so an owner
175	     * with no recorded tenure never qualifies for the tenure-gated points.
176	     */
177	    default long tenureDays(Owner owner) {
178	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
179	        if (registrationDate == null) {
180	            return 0;
181	        }
182	        long days = java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
183	        return Math.max(days, 0);
184	    }
185	
186	    /**
187	     * Derives the owner's locality (region) at read time from the region-and-hash
188	     * {@code customerCode}: its {@code REGION} prefix (e.g. {@code NSW} for {@code NSW-1A2B3C4D}),
189	     * so the region cannot drift from the identity every other derived value flows through. Owners
190	     * with no {@code customerCode} fall back to resolving the region directly. Both the parse and
191	     * the fallback (including the {@code UNKNOWN} sentinel) live in {@code OwnerCustomerCode}.
192	     */
193	    default String locality(Owner owner) {
194	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
195	            .regionOf(owner.getCustomerCode());
196	        return region != null ? region
197	            : org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
198	                .regionFor(owner);
199	    }
200	
201	    /**
202	     * Derives the owner's timezone at read time: the IANA name for the owner's
203	     * {@link #locality(Owner) locality} (region) from the fixed region-to-timezone table
204	     * (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane). Returns
205	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}), so the field is
206	     * absent for such owners.
207	     */
208	    default String timezone(Owner owner) {
209	        return org.springframework.samples.petclinic.rest.function.owner.OwnerLocality
210	            .timezoneForRegion(locality(owner));
211	    }
212	
213	    Owner toOwner(OwnerDto ownerDto);
214	
215	    @Mapping(target = "id", ignore = true)
216	    @Mapping(target = "pets", ignore = true)
217	    Owner toOwner(OwnerFieldsDto ownerDto);
218	
219	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
220	
221	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
222	
223	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
224	        OwnerPageDto ownerPageDto = new OwnerPageDto();
225	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
226	        ownerPageDto.setPage(ownerPage.getNumber());
227	        ownerPageDto.setSize(ownerPage.getSize());
228	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
229	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
230	        return ownerPageDto;
231	    }
232	}
